    private static function reduceType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        if (\is_array($children)) {
            return $children[0];
        }

        return $children;
    }

    private function reduceConditionalType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!isset($children[1])) {
            return $children[0];
        }

        if (!$this->features->conditions) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('conditions', $ctx);
        }

        return match (\count($children)) {
            // T is U ? A : B
            4 => new Type\Condition\ConditionalTypeNode(
                new Type\Condition\EqualConditionNode($children[0], $children[1], $offset),
                $children[2],
                $children[3],
                $offset,
            ),
            // T is not U ? A : B, the children have the "is not" in front of the target
            default => new Type\Condition\ConditionalTypeNode(
                new Type\Condition\NotEqualConditionNode($children[0], $children[2], $offset),
                $children[3],
                $children[4],
                $offset,
            ),
        };
    }

    private function reduceUnionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!isset($children[1])) {
            return $children[0];
        }

        if (!$this->features->unions) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('unions', $ctx);
        }

        return new Type\LogicalTypeNode\UnionTypeNode($children, $offset);
    }

    private function reduceIntersectionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!isset($children[1])) {
            return $children[0];
        }

        if (!$this->features->intersections) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('intersections', $ctx);
        }

        return new Type\LogicalTypeNode\IntersectionTypeNode($children, $offset);
    }

    private function reduceQuestionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!$this->features->nullables) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('nullables', $ctx);
        }

        return new Type\WrappingTypeNode\NullableTypeNode($children[1], $offset);
    }

    private static function reduceListTypeOrOffsetAccess(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (!\is_array($children)) {
            return $children;
        }

        // The children are the type and the suffixes: "]" for "[]", K for "[K]"
        $type = null;

        foreach ($children as $child) {
            switch (true) {
                case $type === null:
                    $type = $child;
                    break;

                case $child instanceof Type\TypeNode:
                    $type = new Type\WrappingTypeNode\TypeOffsetAccessTypeNode($type, $child, $offset);
                    break;

                default:
                    $type = new Type\WrappingTypeNode\TypesListTypeNode($type, $offset);
                    break;
            }
        }

        return $type;
    }

    private function reduceLiteral(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        if (!$this->features->literals) {
            throw Exception\FeatureNotEnabledException::becauseFeatureIsNotEnabledIn('literals', $ctx);
        }

        return $children;
    }

    private static function reduceKeywordLiteral(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return match ($children->id) {
            self::T_NULL => new Type\Literal\NullLiteralNode($children->value, $offset),
            self::T_TRUE => new Type\Literal\BoolLiteralNode(true, $children->value, $offset),
            default => new Type\Literal\BoolLiteralNode(false, $children->value, $offset),
        };
    }

